-- =============================================================================
-- 0012_map_packed.sql — get_map() for the 111,111-plot map.
--
-- The map grows from 7,048 plots (2x2 km, 135 columns) to exactly 111,111
-- plots of 500x500 m on a 540 x 537 grid: id = row * 540 + col, so ids go up
-- to 289,979 (< 300,000). 0004_cells_seed.sql is regenerated by
-- tools/make_map.py for the new grid; the map_cells table (0003a) is unchanged.
--
-- With tens of thousands of lit plots the JSON arrays of get_map() get too big
-- (~20 bytes per lit plot), so `lit` and `held` are replaced by packed binary
-- forms (base64, standard alphabet, with padding, no line breaks):
--
--   lit_packed : 4 bytes per lit plot, ordered by cell_id:
--                  byte0 = (id >> 16) & 255
--                  byte1 = (id >>  8) & 255
--                  byte2 =  id        & 255
--                  byte3 = (icon_index << 4) | (color_index << 1) | big
--                icon_index / color_index = positions (0..5) in
--                  icons  tree home candle star gift pomegranate
--                  colors amber red green white blue violet
--                big = 1 for light_big, else 0.
--   held_packed: 3 bytes per held plot (unexpired, unpaid hold), ordered by
--                cell_id, same id encoding (byte0..byte2).
--
-- Empty lists are "" (empty string). Every other key is unchanged:
-- total, lit_count, by_province, warm, updated_at.
--
-- Encoding: int4send() gives 4 big-endian bytes, so for 0 <= id < 2^23
--   int4send((id << 8) | byte3)        = the 4 lit bytes
--   substring(int4send(id) from 2)     = the 3 held bytes
-- string_agg(bytea, '' order by ...) concatenates them (ordering by the lit
-- word is ordering by cell_id: the id is its high 24 bits) and
-- encode(..., 'base64') makes the text; PostgreSQL inserts a newline every
-- 76 characters, which replace(..., E'\n', '') removes.
--
-- Speed (local PostgreSQL 16, 111,111 plots, 100,000 lit, 301 held):
-- ~135 ms per call, 535 KB JSON (lit_packed 533,336 chars). The function runs
-- with work_mem = 32MB so the 100k-row sort stays in memory (with the 4MB
-- default it spilled to disk). by_province now counts in one grouped pass.
-- cell_holds_open_idx keeps `held_packed` an index scan of the open holds only.
--
-- Apply after 0011_room_warmth. create or replace keeps the grants; restated.
-- =============================================================================

-- `held` scans only the few holds of open payments instead of every paid light.
create index if not exists cell_holds_open_idx
  on public.cell_holds (expires_at, cell_id)
  where expires_at <> 'infinity';

create or replace function public.get_map()
returns json
language sql
stable
security definer
set search_path = public
set work_mem = '32MB'
as $$
  with lit as (
    select h.cell_id,
           o.id as order_id,
           -- the 4 packed bytes as one integer: id << 8 | icon << 4 | color << 1 | big
           (h.cell_id << 8)
             | (coalesce(array_position(array['tree', 'home', 'candle', 'star', 'gift', 'pomegranate'], o.light_icon) - 1, 0) << 4)
             | (coalesce(array_position(array['amber', 'red', 'green', 'white', 'blue', 'violet'], o.light_color) - 1, 0) << 1)
             | (case when o.product = 'light_big' then 1 else 0 end) as word
      from public.cell_holds h
      join public.orders o on o.id = h.order_id
     where h.expires_at = 'infinity' and o.status = 'paid'
  ), provinces(code, sort) as (
    values ('yer', 1), ('ara', 2), ('arm', 3), ('ag', 4), ('kt', 5), ('gr', 6),
           ('sh', 7), ('lo', 8), ('tv', 9), ('vd', 10), ('su', 11)
  ), warm as (
    select s.cell_id, s.warmth
      from public.room_stats s
      join lit on lit.cell_id = s.cell_id and lit.order_id = s.order_id
     where s.warmth > 0
     order by s.warmth desc, s.cell_id
     limit 50
  )
  select json_build_object(
    'lit_packed',  replace(encode(coalesce(
                     (select string_agg(int4send(word), ''::bytea order by word)
                        from lit),
                     ''::bytea), 'base64'), E'\n', ''),
    'held_packed', replace(encode(coalesce(
                     (select string_agg(substring(int4send(h.cell_id) from 2), ''::bytea order by h.cell_id)
                        from public.cell_holds h
                       where h.expires_at <> 'infinity' and h.expires_at > now()),
                     ''::bytea), 'base64'), E'\n', ''),
    'total',       (select count(*) from public.map_cells),
    'lit_count',   (select count(*) from lit),
    -- one pass over lit (0011 scanned it once per province)
    'by_province', (select json_object_agg(p.code, coalesce(n.cnt, 0) order by p.sort)
                      from provinces p
                      left join (select c.province, count(*) as cnt
                                   from lit join public.map_cells c on c.id = lit.cell_id
                                  group by c.province) n on n.province = p.code),
    'warm',        coalesce((select json_agg(json_build_array(cell_id, warmth) order by warmth desc, cell_id) from warm),
                            '[]'::json),
    'updated_at',  now()
  );
$$;

revoke all on function public.get_map() from public;
grant execute on function public.get_map() to anon, authenticated, service_role;
